beforeExample:
package test;
import org.eclipse.swt.widgets.Combo;
import org.eclipse.swt.graphics.Point;

public class TestClass {
    Combo fCombo;

    public int getCaretOffset() {
        if (fCombo == null) return -1;
        return fCombo.getSelection().y;
    }
}

afterExample:
package test;
import org.eclipse.swt.widgets.Combo;
//import org.eclipse.swt.graphics.Point; // Point import might be removed if not used elsewhere

public class TestClass {
    Combo fCombo;

    public int getCaretOffset() {
        if (fCombo == null) return -1;
        return fCombo.getCaretPosition();
    }
}

negativeExample:
package test;
import org.eclipse.swt.graphics.Point;

class MyCustomControl {
    Point getSelection() { return new Point(0, 5); }
}

public class NegativeTestClass {
    MyCustomControl myControl;
    public int getCaretOffset() {
        // This should not match because myControl is not an instance of Combo
        if (myControl == null) return -1;
        return myControl.getSelection().y;
    }
}
